#include <stdio.h>



int main(void) {
    for (int n = 100; n <= 999; n++) {
        int a = n / 100, b = n / 10 % 10, c = n % 10;
        if (n == a*a*a + b*b*b + c*c*c) printf("%d ", n);
    }
    putchar('\n');
    return 0;
}
